+	tx, err := s.db.Begin()
+	if err != nil {
+		return nil, err
+	}
+	defer tx.Rollback()
+
+	countStatement, err := tx.Prepare(`
+SELECT COUNT(1) FROM service_instances
+WHERE service_name = ? AND instance_id = ?`)
+	if err != nil {
+		return nil, err
+	}
